Giải hệ phương trình $\begin{cases}
\dfrac{3}{4 y - 4} + \dfrac{2}{x - 2}=\dfrac{5}{4} \\ 
         \dfrac{1}{4 y - 4} + \dfrac{4}{x - 2}=\dfrac{25}{12}
\end{cases}$.  
\loigiai{
Đặt $\dfrac{1}{x - 2} = u, \dfrac{1}{4 y - 4} =v $\\
ta có hệ phương trình $\begin{cases}
2 u + 3 v=\dfrac{5}{4} \\ 
                        4 u + v=\dfrac{25}{12}
\end{cases} $\\
$\begin{cases}
u=\dfrac{1}{2} \\ 
                        v=\dfrac{1}{12}
\end{cases}$\\
$\begin{cases}
\dfrac{1}{x - 2}=\dfrac{1}{2} \\ 
                        \dfrac{1}{4 y - 4}=\dfrac{1}{12}
\end{cases}$\\
$\begin{cases}
x=4 \\ 
                            y=4
\end{cases}$
}\end{ex}

\begin{ex}%[9D1C2-3]
Giải hệ phương trình $\begin{cases}
\dfrac{4}{4 y - 1} + \dfrac{1}{3 x - 4}=-5 \\ 
         \dfrac{1}{4 y - 1} + \dfrac{2}{3 x - 4}=-3
\end{cases}$.  
\loigiai{
Đặt $\dfrac{1}{3 x - 4} = u, \dfrac{1}{4 y - 1} =v $\\
ta có hệ phương trình $\begin{cases}
u + 4 v=-5 \\ 
                        2 u + v=-3
\end{cases} $\\
$\begin{cases}
u=-1 \\ 
                        v=-1
\end{cases}$\\
$\begin{cases}
\dfrac{1}{3 x - 4}=-1 \\ 
                        \dfrac{1}{4 y - 1}=-1
\end{cases}$\\
$\begin{cases}
x=1 \\ 
                            y=0
\end{cases}$
}\end{ex}

