\shortans{17}

\loigiai{
Diện tích vườn hoa là $S= \pi R^{2}= 16 \pi (m^{2})$\\
Diện tích trồng mỗi loại hoa là $16 \pi : 3 \approx 17 (m^{2})$
}\end{ex}

