\draw[<->] (-2.6,0.4)--(2.6,0.4) node[midway, above] {$s=9\,\text{m}$};
\draw[<->, blue!75!black] (-2.6,-0.7)--(-1.4,-0.7) node[midway, above] {$x$};
\draw[<->, blue!75!black] (1.4,-0.7)--(2.6,-0.7) node[midway, above] {$x$};
\draw[<->, red!75!black] (2.8,0)--(2.8,-1.4) node[midway, right] {$x$};
\node[below] at (0,-0.4) {$2R=9-2x$};
